7	export type WithMeta = { _meta?: Record<string, unknown> };
8	
9	export type Unsubscribe = () => void;
10	
11	export interface AgentProtocol extends Trajectory {
12	  /**
13	   * Send data to the agent. Promise resolves when action is acknowledged.
14	   * Returns the `streamId` of the stream the message was correlated to --
15	   * this may be a new stream if idle, an existing stream, or null if no
16	   * stream was triggered.
17	   *
18	   * When a new stream is created by a send, the streamId MUST be returned
19	   * before the `agent_start` event is emitted for the stream.
20	   */
21	  send(payload: AgentSend): Promise<{ streamId: string | null }>;
22	
23	  /**
24	   * Subscribes the provided callback to all future events emitted by this
25	   * session. Returns an unsubscribe function.
26	   *
27	   * @param callback The callback function to listen to events.
28	   */
29	  subscribe(callback: (event: AgentEvent) => void): Unsubscribe;
30	
31	  /**
32	   * Aborts an active stream of agent activity.
33	   */
34	  abort(): Promise<void>;
35	
36	  /**
37	   * AgentProtocol implements the Trajectory interface and can retrieve existing events.
38	   */
39	  readonly events: AgentEvent[];
40	}
41	
42	type RequireExactlyOne<T> = {
43	  [K in keyof T]: Required<Pick<T, K>> &
44	    Partial<Record<Exclude<keyof T, K>, never>>;
45	}[keyof T];
46	
47	interface AgentSendPayloads {
48	  message: ContentPart[];
49	  elicitations: ElicitationResponse[];
50	  update: { title?: string; model?: string; config?: Record<string, unknown> };
51	  action: { type: string; data: unknown };
52	}
53	
54	export type AgentSend = RequireExactlyOne<AgentSendPayloads> & WithMeta;
55	
56	export interface Trajectory {
57	  readonly events: AgentEvent[];
58	}
59	
60	export interface AgentEventCommon {
61	  /** Unique id for the event. */
62	  id: string;
63	  /** Identifies the subagent thread, omitted for "main thread" events. */
64	  threadId?: string;
65	  /** Identifies a particular stream of a particular thread. */
66	  streamId?: string | null;
67	  /** ISO Timestamp for the time at which the event occurred. */
68	  timestamp: string;
69	  /** The concrete type of the event. */
70	  type: string;
71	
72	  /** Optional arbitrary metadata for the event. */
73	  _meta?: {
74	    /** source of the event e.g. 'user' | 'ext:{ext_name}/hooks/{hook_name}' */
75	    source?: string;
76	    [key: string]: unknown;
77	  };
78	}
79	
80	export type AgentEventData<
81	  EventType extends keyof AgentEvents = keyof AgentEvents,
82	> = AgentEvents[EventType] & { type: EventType };
83	
84	export type AgentEvent<
85	  EventType extends keyof AgentEvents = keyof AgentEvents,
86	> = AgentEventCommon & AgentEventData<EventType>;
87	
88	export interface AgentEvents {
89	  /** MUST be the first event emitted in a session. */
90	  initialize: Initialize;
91	  /** Updates configuration about the current session/agent. */
92	  session_update: SessionUpdate;
93	  /** Message content provided by user, agent, or developer. */
94	  message: Message;
95	  /** Event indicating the start of agent activity on a stream. */
96	  agent_start: AgentStart;
97	  /** Event indicating the end of agent activity on a stream. */
98	  agent_end: AgentEnd;
99	  /** Tool request issued by the agent. */
100	  tool_request: ToolRequest;
101	  /** Tool update issued by the agent. */
102	  tool_update: ToolUpdate;
103	  /** Tool response supplied by the agent. */
104	  tool_response: ToolResponse;
105	  /** Elicitation request to be displayed to the user. */
106	  elicitation_request: ElicitationRequest;
107	  /** User's response to an elicitation to be returned to the agent. */
108	  elicitation_response: ElicitationResponse;
109	  /** Reports token usage information. */
110	  usage: Usage;
111	  /** Report errors. */
112	  error: ErrorData;
113	  /** Custom events for things not otherwise covered above. */
114	  custom: CustomEvent;
115	}
116	
117	/** Initializes a session by binding it to a specific agent and id. */
118	export interface Initialize {
119	  /** The unique identifier for the session. */
120	  sessionId: string;
121	  /** The unique location of the workspace (usually an absolute filesystem path). */
122	  workspace: string;
123	  /** The identifier of the agent being used for this session. */
124	  agentId: string;
125	  /** The schema declared by the agent that can be used for configuration. */
126	  configSchema?: Record<string, unknown>;
127	}
128	
129	/** Updates config such as selected model or session title. */
130	export interface SessionUpdate {
131	  /** If provided, updates the human-friendly title of the current session. */
132	  title?: string;
133	  /** If provided, updates the model the current session should utilize. */
134	  model?: string;
135	  /** If provided, updates agent-specific config information. */
136	  config?: Record<string, unknown>;
137	}
138	
139	export type ContentPart =
140	  /** Represents text. */
141	  (
142	    | { type: 'text'; text: string }
143	    /** Represents model thinking output. */
144	    | { type: 'thought'; thought: string; thoughtSignature?: string }
145	    /** Represents rich media (image/video/pdf/etc) included inline. */
146	    | { type: 'media'; data?: string; uri?: string; mimeType?: string }
147	    /** Represents an inline reference to a resource, e.g. @-mention of a file */
148	    | {
149	        type: 'reference';
150	        text: string;
151	        data?: string;
152	        uri?: string;
153	        mimeType?: string;
154	      }
155	  ) &
156	    WithMeta;
157	
158	export interface Message {
159	  role: 'user' | 'agent' | 'developer';
160	  content: ContentPart[];
161	}
162	
163	export interface ToolRequest {
164	  /** A unique identifier for this tool request to be correlated by the response. */
165	  requestId: string;
166	  /** The name of the tool being requested. */
167	  name: string;
168	  /** The arguments for the tool. */
169	  args: Record<string, unknown>;
170	}
171	
172	/**
173	 * Used to provide intermediate updates on long-running tools such as subagents
174	 * or shell commands. ToolUpdates are ephemeral status reporting mechanisms only,
175	 * they do not affect the final result sent to the model.
176	 */
177	export interface ToolUpdate {
178	  requestId: string;
179	  displayContent?: ContentPart[];
180	  content?: ContentPart[];
181	  data?: Record<string, unknown>;
182	}
183	
184	export interface ToolResponse {
185	  requestId: string;
186	  name: string;
187	  /** Content representing the tool call's outcome to be presented to the user. */
188	  displayContent?: ContentPart[];
189	  /** Multi-part content to be sent to the model. */
190	  content?: ContentPart[];
191	  /** Structured data to be sent to the model. */
192	  data?: Record<string, unknown>;
193	  /** When true, the tool call encountered an error that will be sent to the model. */
194	  isError?: boolean;
195	}
196	
197	export type ElicitationRequest = {
198	  /**
199	   * Whether the elicitation should be displayed as part of the message stream or
200	   * as a standalone dialog box.
201	   */
202	  display: 'inline' | 'modal';
203	  /** An optional heading/title for longer-form elicitation requests. */
204	  title?: string;
205	  /** A unique ID for the elicitation request, correlated in response. */
206	  requestId: string;
207	  /** The question / content to display to the user. */
208	  message: string;
209	  requestedSchema: Record<string, unknown>;
210	} & WithMeta;
211	
212	export type ElicitationResponse = {
213	  requestId: string;
214	  action: 'accept' | 'decline' | 'cancel';
215	  content: Record<string, unknown>;
216	} & WithMeta;
217	
