10	/**
11	 * Converts Gemini API Part objects to framework-agnostic ContentPart objects.
12	 * Handles text, thought, inlineData, fileData parts and serializes unknown
13	 * part types to text to avoid silent data loss.
14	 */
15	export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
16	  const result: ContentPart[] = [];
17	  for (const part of parts) {
18	    if ('text' in part && part.text !== undefined) {
19	      if ('thought' in part && part.thought) {
20	        result.push({
21	          type: 'thought',
22	          thought: part.text,
23	          ...(part.thoughtSignature
24	            ? { thoughtSignature: part.thoughtSignature }
25	            : {}),
26	        });
27	      } else {
28	        result.push({ type: 'text', text: part.text });
29	      }
30	    } else if ('inlineData' in part && part.inlineData) {
31	      result.push({
32	        type: 'media',
33	        data: part.inlineData.data,
34	        mimeType: part.inlineData.mimeType,
35	      });
36	    } else if ('fileData' in part && part.fileData) {
37	      result.push({
38	        type: 'media',
39	        uri: part.fileData.fileUri,
40	        mimeType: part.fileData.mimeType,
41	      });
42	    } else if ('functionCall' in part && part.functionCall) {
43	      continue; // Skip function calls, they are emitted as distinct tool_request events
44	    } else if ('functionResponse' in part && part.functionResponse) {
45	      continue; // Skip function responses, they are tied to tool_response events
46	    } else {
47	      // Fallback: serialize any unrecognized part type to text
48	      result.push({
49	        type: 'text',
50	        text: JSON.stringify(part),
51	        _meta: { partType: 'unknown' },
52	      });
53	    }
54	  }
55	  return result;
56	}
