122	/**
123	 * Builds the data record for a tool_response AgentEvent, preserving
124	 * all available metadata from the ToolCallResponseInfo.
125	 */
126	export function buildToolResponseData(response: {
127	  data?: Record<string, unknown>;
128	  errorType?: string;
129	  outputFile?: string;
130	  contentLength?: number;
131	}): Record<string, unknown> | undefined {
132	  const parts: Record<string, unknown> = {};
133	  if (response.data) Object.assign(parts, response.data);
134	  if (response.errorType) parts['errorType'] = response.errorType;
135	  if (response.outputFile) parts['outputFile'] = response.outputFile;
136	  if (response.contentLength !== undefined)
137	    parts['contentLength'] = response.contentLength;
138	  return Object.keys(parts).length > 0 ? parts : undefined;
139	}
